head.script:
// ===== 리턴 값 출력 영역 =====
scwin.btn_clear_onclick = function (e) {
    $p.getComponentById("tbx_return").setValue("");
};

scwin.setReturnValue = function (strValue) {
    var objReturn = $p.getComponentById("tbx_return");
    objReturn.setValue(objReturn.getValue() + strValue);
    objReturn.setValue(objReturn.getValue() + "\n");
};

// ===== 결함 재현 (5.0 vs 6.0 동작 비교) =====
scwin.setTargetDisabled = function (bDisabled) {
    var objComp = $p.getComponentById("target1");
    objComp.setDisabled(bDisabled);
    scwin.setReturnValue("[setDisabled(" + bDisabled + ")] getDisabled : " + objComp.getDisabled());
};

scwin.btn_disable_onclick = function (e) {
    scwin.setTargetDisabled(true);
};

scwin.btn_enable_onclick = function (e) {
    scwin.setTargetDisabled(false);
};

// 대상 editor 의 onclick 핸들러 (발생하면 결과창에 기록)
scwin.target1_onclick = function (e) {
    scwin.setReturnValue("=====editor onclick 이벤트 발생=====  getDisabled : "
        + $p.getComponentById("target1").getDisabled());
};
